import datetime, re
try:
    e = str(vars.get('id_event', 'none'))
    vars['id_event'] = 'none'
    vars['id_action'] = 'none'
    for k, v in [('id_phase', 'name'), ('id_name_asks', 1), ('id_declines', 0), ('talk_declines', 0), ('human_asks', 0), ('callback_invalid', 0), ('finish_state', 'open'), ('resolution_outcome', ''), ('resolution_reason', '')]:
        vars.setdefault(k, v)
    phase = str(vars['id_phase'])
    q = str(vars.get('id_question', 'none'))
    vars['id_question'] = 'none'
    vars['id_instruction'] = 'Ask only the missing part of the current question.'
    if vars.get('transfer_last_state') == 'failed':
        vars['transfer_last_state'] = 'none'
    lead = ''
    if q == 'ai' or (q == 'about' and phase == 'name'):
        lead = "I am Freya Bank's digital assistant. "
    elif q == 'scam':
        lead = "You can verify this call by phoning Freya Bank's customer service number. "
    elif q == 'unknown':
        lead = 'I do not have that information. '
    if q == 'about' and phase in ['dob', 'phone'] and e in ['question', 'name_question']:
        e = 'decline'
    if e == 'question' and phase == 'name':
        e = 'name_question'
    def finish(outcome, reason, instruction):
        vars['resolution_outcome'] = outcome
        vars['resolution_reason'] = reason
        vars['resolution_message'] = instruction
        vars['finish_state'] = 'ready'
        vars['id_instruction'] = instruction
    def repeat_name():
        n = int(vars.get('id_name_asks', 1))
        if n >= 2:
            finish('not_reached', 'unclear', lead + 'The name was not confirmed after two asks.')
        else:
            vars['id_name_asks'] = n + 1
            vars['id_instruction'] = lead + 'Ask the name-confirmation question once more; this is the second and final ask.'
    holidays = set(['2026-10-26', '2026-11-11', '2026-11-26', '2026-12-25', '2027-01-01'])
    def business(d):
        return d.weekday() < 5 and d.isoformat() not in holidays
    def parse_day(s, today):
        try:
            s = str(s).strip().lower().replace(',', '')
            if s in ['today', 'tomorrow', 'day after tomorrow'] and isinstance(today, datetime.date):
                return today + datetime.timedelta(days=['today', 'tomorrow', 'day after tomorrow'].index(s))
            if re.fullmatch(r'\d{4}-\d{2}-\d{2}', s):
                return datetime.date.fromisoformat(s)
            m = re.fullmatch(r'(\d{1,2})[/.\-](\d{1,2})[/.\-](\d{4})', s)
            if m:
                return datetime.date(int(m.group(3)), int(m.group(2)), int(m.group(1)))
            names = ['monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday', 'sunday']
            m = re.fullmatch(r'(this|next)\s+(' + '|'.join(names) + ')', s)
            if m and isinstance(today, datetime.date):
                return today - datetime.timedelta(days=today.weekday()) + datetime.timedelta(days=names.index(m.group(2)) + (7 if m.group(1) == 'next' else 0))
            for fmt in ['%d %B %Y', '%B %d %Y', '%d %b %Y', '%b %d %Y']:
                try:
                    return datetime.datetime.strptime(s, fmt).date()
                except Exception:
                    pass
            return ''
        except Exception:
            return ''
    if e == 'wrong_number':
        finish('not_reached', 'wrong_number', 'Acknowledge the wrong number without account details.')
    elif e == 'deceased':
        finish('not_reached', 'deceased', 'Say exactly: I am sorry for your loss. Ask nothing else.')
    elif e == 'third_party':
        vars['id_phase'] = 'callback'
        vars['id_instruction'] = 'Disclose no reason or account information. Ask when the customer can be reached.'
    elif e == 'no_callback' and phase == 'callback':
        finish('not_reached', 'no_callback', 'No callback has been scheduled.')
    elif e == 'assist_yes':
        if phase == 'name':
            repeat_name()
        elif phase == 'dob':
            vars['id_instruction'] = 'Ask for the customer\'s date of birth. Agreement to assistance is not a security answer.'
        elif phase == 'phone':
            vars['id_instruction'] = 'Ask only for the last four digits of the phone number on file. Do not repeat the passed birth-date question.'
        else:
            vars['id_instruction'] = 'Ask when the customer can be reached. Agreement to assistance did not authorize a callback.'
    elif e == 'assist_no':
        vars['id_instruction'] = 'Acknowledge that they do not want further assistance. The failed transfer alone establishes no closing outcome; do not claim success, disclose account information, or repeat the transfer automatically.'
    elif e == 'human':
        if int(vars.get('human_asks', 0)) == 0:
            vars['human_asks'] = 1
            vars['id_instruction'] = 'Ask once: May I help you first? Agreement to this question is not name confirmation or a security answer.'
        else:
            vars['requested_queue'] = 'general'
            vars['id_action'] = 'transfer'
            vars['id_instruction'] = 'CALL transfer_to_agent now with queue general. Do not claim success before its result.'
    elif e == 'stop':
        n = int(vars.get('talk_declines', 0)) + 1
        vars['talk_declines'] = n
        if phase in ['dob', 'phone']:
            vars['id_declines'] = int(vars.get('id_declines', 0)) + 1
        if phase == 'callback':
            finish('not_reached', 'no_callback', 'No callback has been scheduled.')
        elif n >= 2 or (phase in ['dob', 'phone'] and int(vars['id_declines']) >= 2):
            finish('not_verified', 'declined', 'Respect the refusal; disclose no account details.')
        else:
            vars['id_instruction'] = 'Acknowledge briefly. Explain once that the questions protect the account, then ask only the current unanswered question. Disclose no call purpose.'
    elif e == 'decline' and phase in ['dob', 'phone']:
        n = int(vars.get('id_declines', 0)) + 1
        vars['id_declines'] = n
        if n >= 2:
            finish('not_verified', 'declined', 'Respect the identity refusal; disclose no account details.')
        else:
            vars['id_instruction'] = 'Explain once that the security questions protect the account. Ask only the current unanswered security question.'
    elif e == 'name_yes' and phase == 'name':
        vars['id_phase'] = 'dob'
        vars['id_instruction'] = 'Ask for the customer\'s date of birth. Do not ask for phone digits yet.'
    elif e in ['name_unclear', 'name_question'] and phase == 'name':
        repeat_name()
    elif e == 'answer' and phase in ['dob', 'phone']:
        s = str(vars.get('id_answer_text', '')).strip()
        answer = ''
        if phase == 'phone':
            words = dict(zero='0', oh='0', one='1', two='2', three='3', four='4', five='5', six='6', seven='7', eight='8', nine='9')
            parts = re.findall(r'[a-z]+|\d+', s.lower())
            digits = []
            valid = True
            for part in parts:
                if part in words:
                    digits.append(words[part])
                elif part.isdigit():
                    digits.append(part)
                else:
                    valid = False
            joined = ''.join(digits)
            if valid and re.fullmatch(r'\d{4}', joined):
                answer = joined
            else:
                vars['id_instruction'] = 'Ask only for the missing phone digits, or clarify the corrected four digits if too many were supplied. Do not validate a partial answer.'
        else:
            d = parse_day(s, '') if re.search(r'\d{4}', s) else ''
            if d:
                answer = d.isoformat()
            else:
                vars['id_instruction'] = 'Ask only for the missing or unclear birth-date component. Numeric order is day, month, year. Do not guess or validate a partial date.'
        if answer:
            vars['security_request'] = dict(field='date_of_birth' if phase == 'dob' else 'phone_last4', answer=answer)
            vars['id_action'] = 'verify'
            vars['id_instruction'] = 'CALL verify_identity now using the prepared customer-supplied answer. Do not repeat the question first.'
    elif e == 'callback' and phase == 'callback':
        now = datetime.datetime.fromisoformat(str(vars.get('now', '')).replace('Z', '+00:00')).replace(tzinfo=None)
        today = now.date()
        nxt = today + datetime.timedelta(days=1)
        while not business(nxt):
            nxt += datetime.timedelta(days=1)
        vars['callback_facts'] = dict(today=today.isoformat(), next_business_day=nxt.isoformat(), earliest_time='10:00', latest_time='19:00', strictly_after=now.isoformat())
        ds = str(vars.get('id_day_text', '')).strip()
        ts = str(vars.get('id_time_text', '')).strip()
        d = parse_day(ds, today)
        if not ds or not ts or not d or not re.fullmatch(r'\d{2}:\d{2}', ts):
            vars['id_instruction'] = 'Ask only for the missing or ambiguous exact callback day or time. Allowed dates are ' + today.isoformat() + ' or ' + nxt.isoformat() + ', 10:00 through 19:00, strictly later than now. Do not schedule yet.'
        else:
            valid_time = False
            try:
                stamp = datetime.datetime.combine(d, datetime.time.fromisoformat(ts))
                valid_time = d in [today, nxt] and '10:00' <= ts <= '19:00' and stamp > now
            except Exception:
                pass
            if valid_time:
                vars['authorized_callback'] = dict(date=d.isoformat(), time=ts)
                vars['id_action'] = 'callback'
                vars['id_instruction'] = 'CALL schedule_callback now for the validated customer-requested date ' + d.isoformat() + ' and time ' + ts + '.'
            else:
                n = int(vars.get('callback_invalid', 0)) + 1
                vars['callback_invalid'] = n
                vars['id_day_text'] = ''
                vars['id_time_text'] = ''
                if n >= 2:
                    finish('not_reached', 'no_callback', 'No callback was scheduled because both proposed times were outside the permitted window.')
                else:
                    vars['id_instruction'] = 'Explain the allowed window and ask once for another time: ' + today.isoformat() + ' or ' + nxt.isoformat() + ', 10:00 through 19:00, strictly later than ' + now.isoformat() + '.'
    elif e == 'question':
        vars['id_instruction'] = lead + 'Continue with only the current unanswered question. Do not disclose account details.'
    else:
        vars['id_instruction'] = lead + 'Ask only the current unanswered question; do not infer identity or call a bank tool without a prepared action.'
except Exception:
    vars['id_event'] = 'none'
    vars['id_action'] = 'none'
    vars['id_instruction'] = 'Say that the information could not be interpreted and ask for the missing exact detail. Do not call a bank tool or disclose account information.'

collection.task_message:
Follow this prepared instruction immediately: {{collect_instruction}}
Product and calculated facts: {{fact_text}}
Phase: {{collection_phase}}. Promise-write authorization: {{promise_ready}}.
CALL create_promise only when promise_ready is yes: the current product, amount and date have already been validated and the customer explicitly confirmed that read-back. Use the authorized values, never an earlier offer. After a first failed create_promise, repeat the identical authorized write once as instructed by its result. Never repeat after success or after a second failure. CALL transfer_to_agent only when the prepared instruction requests the stated queue. After a failed transfer, say it did not succeed and continue without claiming a transfer.
For all other instructions, speak the prepared sentence or ask the prepared question now. Do not invent another question about willingness before the required payment question. State all of this call's debt first: this brief has one product. Propose every amount; never ask how much the customer can pay. A date or amount proposal is not a refusal. Use the customer's corrected portion, not the first value. An unrelated date in small talk is not a payment date. Changes at confirmation must go through validation and a fresh complete read-back. A yes qualified by a change is a correction, not confirmation. Do not write a pending promise when the customer instead requests a transfer.
Current payment already made means explain one business day to appear and no promise. Historical payoff, closure or product denial means dispute. Hardship gets sympathy, no persuasion and a support offer, but the customer's voluntary valid proposal can still be confirmed. Hardship overrides a request for restructuring. Other new-plan/lower-instalment requests go to restructuring without describing a plan. Human requests get one help-first question, then general on insistence. A recorded promise cannot be changed or cancelled here; direct changes to the mobile app. Never call add_note. Questions about AI/scams get the prescribed short answer; unknown information is unavailable, not guessed. Do not silently round or alter an accepted amount or date.

proposal_check.code:
import datetime, json, re
try:
    e = str(vars.get('collect_event', 'none'))
    phase = str(vars.get('collection_phase', 'initial'))
    amount_text = str(vars.get('proposed_amount_text', '')).strip()
    date_text = str(vars.get('proposed_date_text', '')).strip()
    if not date_text and phase in ['floor_offer', 'amount_clarify'] and e in ['accept', 'proposal', 'full_too_much']:
        date_text = str(vars.get('pending_date_text', '')).strip()
    new_hardship = str(vars.get('hardship_signal', 'no')) == 'yes' or e == 'hardship'
    question = str(vars.get('collection_question', 'none'))
    assistance = vars.get('assistance_pending') == 'help' or vars.get('transfer_last_state') == 'failed'
    failed_transfer = vars.get('transfer_last_state') == 'failed'
    vars['assistance_pending'] = 'none'
    if failed_transfer:
        vars['transfer_last_state'] = 'none'
    if assistance and e in ['accept', 'support_yes']:
        e = 'assist_yes'
    vars['collect_event'] = 'none'
    vars['proposed_amount_text'] = ''
    vars['proposed_date_text'] = ''
    vars['hardship_signal'] = 'no'
    vars['collection_question'] = 'none'
    vars['promise_ready'] = 'no'
    vars['authorized_promise'] = dict()
    vars['collect_instruction'] = 'Ask for clarification of the current response; do not write a promise.'
    f = vars.get('active_product', dict())
    if isinstance(f, str):
        f = json.loads(f)
    if not isinstance(f, dict) or not f.get('product_id'):
        raise ValueError('No usable product')
    full = float(f['past_due'])
    floor = float(f['floor'])
    today = datetime.date.fromisoformat(str(vars.get('today', str(vars.get('now', ''))[:10])))
    deadline = datetime.date.fromisoformat(str(f['deadline']))
    a = float(vars.get('candidate_amount', full))
    ds = str(vars.get('candidate_date', today.isoformat()))
    sympathy = ''
    if new_hardship and vars.get('hardship_active', 'no') != 'yes':
        sympathy = 'I am sorry you are going through this. '
    if new_hardship:
        vars['hardship_active'] = 'yes'
    hardship = vars.get('hardship_active', 'no') == 'yes'
    if e == 'hardship' and (amount_text or date_text):
        e = 'proposal'
    if e == 'accept' and phase == 'hardship_choice':
        e = 'support_yes'
    if e == 'full_too_much' and date_text and vars.get('floor_offered') == 'yes':
        vars['full_too_much'] = 'yes'
        a = floor
        e = 'proposal'
    records = vars.get('recorded_promises', [])
    if isinstance(records, str):
        records = json.loads(records)
    if not isinstance(records, list):
        records = []
    def finish(outcome, reason, message):
        vars['resolution_outcome'] = outcome
        vars['resolution_reason'] = reason
        vars['resolution_message'] = message
        vars['finish_state'] = 'ready'
        vars['pending_date_text'] = ''
    def transfer(queue):
        vars['requested_queue'] = queue
        vars['collect_instruction'] = sympathy + 'CALL transfer_to_agent now with queue ' + queue + '. Do not create a pending promise.'
    def key(amount, day):
        return str(float(amount)) + '@' + day
    def readback(amount, day, prefix=''):
        vars['candidate_amount'] = amount
        vars['candidate_date'] = day
        vars['pending_date_text'] = ''
        vars['collection_phase'] = 'confirm'
        vars['last_offer_key'] = key(amount, day)
        remainder = ' Say that the rest stays overdue.' if amount < full else ''
        vars['collect_instruction'] = sympathy + prefix + ' Read back ' + str(f['label']) + ', amount ' + str(amount) + ', date ' + day + '. Ask exactly: Do you confirm?' + remainder
    def resume():
        if phase in ['confirm', 'write'] and ds in f['permissible_dates'] and floor <= a <= full:
            readback(a, ds, 'Agreement to assistance did not confirm payment.')
        elif phase == 'hardship_choice':
            if failed_transfer:
                vars['collect_instruction'] = 'Say that the support connection did not succeed. Make no persuasion attempt or automatic transfer retry; respond to the customer\'s next request.'
            else:
                vars['collect_instruction'] = 'Offer to connect them with the customer support team. Agreement to assistance did not accept that transfer.'
        elif phase == 'exact_date' or not ds:
            vars['collection_phase'] = 'exact_date'
            vars['collect_instruction'] = 'Ask for the missing exact payment day. Agreement to assistance did not supply or confirm a date.'
        elif phase == 'amount_clarify':
            vars['collect_instruction'] = 'Restate the currently offered amount and ask whether that is the amount they meant. A later answer still requires the complete payment read-back.'
        else:
            vars['collect_instruction'] = 'Resume the outstanding payment question: ask whether they can pay ' + str(a) + ' for ' + str(f['label']) + ' on ' + ds + '. Agreement to assistance was not payment consent.'
    def refuse():
        vars['pending_date_text'] = ''
        rejected = vars.get('rejected_offers', [])
        if isinstance(rejected, str):
            rejected = json.loads(rejected)
        if not isinstance(rejected, list):
            rejected = []
        old = str(vars.get('last_offer_key', ''))
        if old and old not in rejected:
            rejected.append(old)
        vars['rejected_offers'] = rejected
        used = int(vars.get('persuasion_used', 0))
        limit = int(f['attempt_limit'])
        while used < limit:
            attempt = used + 1
            oa = floor if attempt == 2 or vars.get('full_too_much', 'no') == 'yes' else full
            od = str(f['deadline'] if attempt == 2 else f.get('offer_one', ''))
            if not od or od not in f['permissible_dates']:
                vars['persuasion_used'] = used
                vars['collection_phase'] = 'policy_gap'
                vars['collect_instruction'] = 'Say that you cannot offer another payment date at the moment. Do not invent an offer or closing reason. Respond to a voluntary eligible proposal or an applicable customer request without consuming an unmade persuasion attempt.'
                return
            used = attempt
            if key(oa, od) not in rejected:
                vars['persuasion_used'] = used
                vars['candidate_amount'] = oa
                vars['candidate_date'] = od
                vars['last_offer_key'] = key(oa, od)
                vars['collection_phase'] = 'offer'
                vars['collect_instruction'] = 'Offer ' + str(oa) + ' for ' + str(f['label']) + ' on ' + od + '. Ask if they can make that payment.' + (' Say that the rest stays overdue.' if oa < full else '')
                return
        vars['persuasion_used'] = used
        finish('no_promise', 'refused', 'Stop persuasion; the permitted offers have been used or already rejected.')
    def parse_day(s):
        try:
            s = s.strip().lower().replace(',', '')
            if s in ['today', 'tomorrow', 'day after tomorrow']:
                return today + datetime.timedelta(days=['today', 'tomorrow', 'day after tomorrow'].index(s))
            if re.fullmatch(r'\d{4}-\d{2}-\d{2}', s):
                return datetime.date.fromisoformat(s)
            m = re.fullmatch(r'(\d{1,2})[/.\-](\d{1,2})[/.\-](\d{4})', s)
            if m:
                return datetime.date(int(m.group(3)), int(m.group(2)), int(m.group(1)))
            names = ['monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday', 'sunday']
            m = re.fullmatch(r'(this|next)\s+(' + '|'.join(names) + ')', s)
            if m:
                return today - datetime.timedelta(days=today.weekday()) + datetime.timedelta(days=names.index(m.group(2)) + (7 if m.group(1) == 'next' else 0))
            for fmt in ['%d %B %Y', '%B %d %Y', '%d %b %Y', '%b %d %Y']:
                try:
                    return datetime.datetime.strptime(s, fmt).date()
                except Exception:
                    pass
            return ''
        except Exception:
            return ''
    if e == 'assist_yes':
        resume()
    elif e == 'assist_no':
        vars['collect_instruction'] = 'Acknowledge that they do not want further assistance. Do not claim that the failed transfer succeeded, retry automatically, or invent a closing outcome from its failure.'
    elif e == 'human':
        if int(vars.get('human_asks', 0)) == 0:
            vars['human_asks'] = 1
            vars['assistance_pending'] = 'help'
            vars['collect_instruction'] = 'Ask once: May I help you first? Agreement is not payment confirmation.'
        else:
            transfer('general')
    elif records:
        if e == 'plan' and not hardship:
            transfer('restructuring')
        elif e == 'support_yes':
            transfer('support')
        elif new_hardship:
            vars['collection_phase'] = 'hardship_choice'
            vars['collect_instruction'] = sympathy + 'Offer to connect them with the customer support team. Do not alter the recorded promise.'
        else:
            finish('promise', '', 'If a change or cancellation was requested, explain that it can be changed in the mobile app. Preserve the recorded promise.')
    elif e == 'paid':
        finish('paid', '', 'Say that payments can take one business day to appear. Do not take a promise.')
    elif e == 'dispute':
        finish('no_promise', 'dispute', 'Acknowledge the dispute without arguing. Do not take a promise.')
    elif e == 'support_yes' and hardship:
        transfer('support')
    elif e == 'support_no' and hardship:
        finish('no_promise', 'hardship', sympathy + 'Respect the declined support offer. Make no persuasion attempt.')
    elif e == 'stop':
        n = int(vars.get('talk_declines', 0)) + 1
        vars['talk_declines'] = n
        if n >= 2:
            finish('no_promise', 'refused', 'Respect the second statement that they do not want to talk.')
        else:
            vars['collect_instruction'] = 'Acknowledge briefly that they do not want to talk. Do not invent a promise or claim the call is closed.'
    elif e == 'question':
        lead = "I am Freya Bank's digital assistant." if question == 'ai' else ("You can verify this call by phoning Freya Bank's customer service number." if question == 'scam' else 'I do not have that information.')
        if new_hardship:
            vars['collection_phase'] = 'hardship_choice'
            vars['collect_instruction'] = sympathy + lead + ' Offer to connect them with the customer support team; make no persuasion attempt.'
        else:
            vars['collect_instruction'] = lead + ' Then resume the current unanswered payment or confirmation question without consuming persuasion.'
    elif hardship and (e not in ['proposal', 'vague_date', 'accept'] or (new_hardship and e == 'accept' and not amount_text and not date_text)):
        if phase == 'hardship_choice' and e == 'refusal':
            finish('no_promise', 'hardship', sympathy + 'Respect the declined support offer. Make no persuasion attempt.')
        else:
            vars['collection_phase'] = 'hardship_choice'
            vars['collect_instruction'] = sympathy + 'Offer to connect them with the customer support team. Do not propose a new payment amount or persuasion date.'
    elif e == 'plan':
        transfer('restructuring')
    elif e == 'refusal':
        refuse()
    elif e == 'full_too_much':
        vars['full_too_much'] = 'yes'
        if vars.get('floor_offered', 'no') != 'yes':
            vars['floor_offered'] = 'yes'
            vars['candidate_amount'] = floor
            vars['pending_date_text'] = date_text
            vars['collection_phase'] = 'floor_offer'
            vars['last_offer_key'] = key(floor, ds)
            vars['collect_instruction'] = 'Offer the floor amount ' + str(floor) + ' once. Say that the rest stays overdue. Ask whether they accept that amount. Preserve any volunteered date for validation and the complete read-back after acceptance.'
        else:
            refuse()
    elif e in ['proposal', 'vague_date', 'accept']:
        prefix = ''
        valid_amount = True
        if amount_text:
            if not re.fullmatch(r'\d+(?:\.\d+)?', amount_text):
                valid_amount = False
                vars['collection_phase'] = 'amount_clarify'
                vars['pending_date_text'] = date_text
                vars['collect_instruction'] = 'The proposed amount was unclear. Restate the currently offered amount and ask whether that is the amount they meant. Do not ask how much they can pay. A yes to this clarification still requires a complete product, amount and date read-back.'
            else:
                a = float(amount_text)
                if a < floor:
                    valid_amount = False
                    vars['full_too_much'] = 'yes'
                    vars['candidate_amount'] = floor
                    vars['pending_date_text'] = date_text
                    vars['collection_phase'] = 'floor_offer'
                    vars['last_offer_key'] = key(floor, ds)
                    if vars.get('floor_offered', 'no') != 'yes':
                        vars['floor_offered'] = 'yes'
                        vars['collect_instruction'] = sympathy + 'Explain that an amount below ' + str(floor) + ' cannot be recorded. Offer ' + str(floor) + ' once and say that the rest stays overdue. Ask whether they accept this amount; preserve their proposed date for the subsequent validation and complete read-back.'
                    else:
                        vars['collect_instruction'] = 'Explain that the proposed amount is below the permitted floor. Ask whether they accept the floor already offered. Preserve their proposed date; do not count the amount proposal itself as refusal.'
                elif a > full or a >= float('inf'):
                    a = full
                    prefix = 'Explain that the full past-due amount is ' + str(full) + ' and offer that amount; it has not yet been accepted.'
        if valid_amount:
            vars['candidate_amount'] = a
            vars['pending_date_text'] = ''
            date_value = parse_day(date_text) if date_text else parse_day(ds)
            vague = e == 'vague_date' or bool(re.search(r'next week|end of (the )?month|salary|payday|sometime', date_text.lower()))
            if vague:
                if int(vars.get('date_clarifications', 0)) == 0:
                    vars['date_clarifications'] = 1
                    vars['collection_phase'] = 'exact_date'
                    vars['candidate_date'] = ''
                    vars['collect_instruction'] = sympathy + 'Ask once for the exact payment day. Do not count this as a refusal.'
                    date_value = ''
                else:
                    date_value = deadline
                    prefix = 'The exact day is still unspecified. Offer the deadline ' + deadline.isoformat() + '.'
            elif not date_value:
